const toggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('#main-nav');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle?.getAttribute('aria-expanded')==='true'){toggle.setAttribute('aria-expanded','false');nav.classList.remove('open');toggle.focus()}});
const form=document.querySelector('#reflection-form');
const status=document.querySelector('#reflection-status');
function getNotes(){const values=new FormData(form);return `THIS WEEK’S COMMITMENT\nSteady & True — Josh Barbee\n\nFocus: ${values.get('focus')}\n\nWhat have I been putting off?\n${values.get('pattern').trim()||'(Not answered)'}\n\nWhat will I do this week, and by when?\n${values.get('change').trim()||'(Not answered)'}\n\nHow will I account for it?\n${values.get('step').trim()||'(Not answered)'}\n`;}
function hasNotes(){if(form.elements.change.value.trim())return true;status.textContent='Write the action you will take this week before saving or copying.';form.elements.change.focus();return false;}
form?.addEventListener('submit',event=>{event.preventDefault();if(!hasNotes())return;const blob=new Blob([getNotes()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='my-steady-and-true-commitment.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Your download has started. Your commitment has not been sent to anyone.';});
document.querySelector('#copy-reflection')?.addEventListener('click',async()=>{if(!hasNotes())return;try{await navigator.clipboard.writeText(getNotes());status.textContent='Copied to your clipboard. Keep your commitment where you’ll see it.';}catch{status.textContent='Copying isn’t available in this browser. Use “Save my commitment” to download your commitment.';}});
